+    device::PDLTriggerSecondary<kUsePDL>();
+    return;
+  }
+  for (int32_t r = 0; r < params.compress_ratio; ++r) {
+    if (locs[r] < 0 || locs[r] >= params.state_slots) {
+      device::PDLTriggerSecondary<kUsePDL>();
